36	// through the link (assembled by concatenation so later tests can keep a raw
37	// ".." segment). relTarget says whether the link target text is relative
38	// (resolved against work, not the process working directory).
39	func danglingDirLinkFixture(t *testing.T, root, linkTarget string) (workDir, aliasPath string) {
40		t.Helper()
