52	// rawPath joins parts with the OS separator WITHOUT lexical cleaning, so a
53	// ".." deliberately placed behind a directory link survives to Load.
54	func rawPath(parts ...string) string {
55		return strings.Join(parts, string(os.PathSeparator))
56	}
