58	// assertDanglingDirLinkLoadFailure checks the Load contract for an
59	// unresolvable directory link: a non-nil error, a nil registry (never an
60	// empty fresh one), and an error that quotes the exact path the caller
61	// passed and explains that a directory symbolic link target cannot be
62	// resolved rather than merely announcing a not-yet-created registry file.
63	func assertDanglingDirLinkLoadFailure(t *testing.T, userPath string) {
64		t.Helper()
65		reg, existed, err := Load(userPath)
66		if err == nil {
67			t.Fatalf("Load(%q) must reject a path through a dangling directory link, got reg=%+v existed=%v", userPath, reg, existed)
68		}
69		if reg != nil {
70			t.Fatalf("Load(%q) must return a nil registry on failure, got %+v", userPath, reg)
71		}
72		if !existed {
73			t.Errorf("Load(%q) must not signal a first registration through an unresolvable link: existed=%v", userPath, existed)
74		}
75		msg := err.Error()
76		if !strings.Contains(msg, userPath) {
77			t.Errorf("error %q must quote the registry path the caller passed verbatim: %q", msg, userPath)
78		}
79		if !strings.Contains(msg, "symbolic link") {
80			t.Errorf("error %q must name the unresolvable symbolic link", msg)
81		}
82		if !strings.Contains(msg, "target") || !strings.Contains(msg, "resolve") {
83			t.Errorf("error %q must explain that the directory link target cannot be resolved", msg)
84		}
85		if strings.Contains(msg, "has not been created") {
86			t.Errorf("error %q must not pretend the registry file has merely not been created", msg)
87		}
88	}
