90	// assertLinkAndFilesUnchanged fails if Load left any trace: the link target
91	// text changed, the named files differ from their pinned bytes/mtime, or a
92	// stray file (a created target, a temporary file) appeared under root.
93	func assertLinkAndFilesUnchanged(t *testing.T, root, aliasPath, linkTarget string, pinned map[string]pinnedFile) {
94		t.Helper()
95		assertLinkIntact(t, aliasPath, linkTarget)
96		for path, want := range pinned {
97			got, err := os.ReadFile(path)
98			if err != nil {
99				t.Fatal(err)
100			}
101			if string(got) != want.content {
102				t.Fatalf("Load changed %s:\nbefore %s\nafter  %s", path, want.content, got)
103			}
104			if info, err := os.Stat(path); err != nil {
105				t.Fatal(err)
106			} else if !info.ModTime().Equal(want.pinned) {
107				t.Fatalf("Load moved the mtime of %s: got %v want %v", path, info.ModTime(), want.pinned)
108			}
109		}
110		assertNoLeftoverTempFiles(t, root)
111	}
