120	// both relative and absolute link targets. A relative target is judged from
121	// the link's own directory; the fixture deliberately makes the same relative
122	// text unresolvable from the process working directory as well, so a
123	// working-directory-relative resolution cannot pass by accident.
124	func TestLoadRejectsDanglingDirectorySymlink(t *testing.T) {
125		cases := []struct {
126			name       string
127			linkTarget func(root string) string
128		}{
129			{"relative target", func(root string) string {
130				return filepath.Join("..", "store", "missing-child")
131			}},
