145				// Read-only: the missing target directory and registry file are
146				// not brought into existence, the link is untouched, and no
147				// temporary file is prepared anywhere.
148				assertLinkIntact(t, aliasPath, target)
149				for _, p := range []string{
150					filepath.Join(root, "store"),
151					filepath.Join(root, "store", "missing-child"),
152					filepath.Join(aliasPath, "batches.json"),
153				} {
