333		}
334		if existed || reg == nil || reg.Version != FormatVersion || len(reg.Batches) != 0 {
335			t.Fatalf("want empty version-1 registry with existed=false, got reg=%+v existed=%v", reg, existed)
336		}
337		if _, err := os.Lstat(filepath.Join(root, "new")); !os.IsNotExist(err) {
338			t.Fatalf("Load must not create missing parent directories, stat err=%v", err)
339		}
340	}
341	
342	// A valid directory link into a real directory where the registry file simply
343	// does not exist yet is an ordinary first registration: empty version-1
344	// registry, existed == false, nothing created.
345	func TestLoadThroughValidDirectorySymlinkMissingFileIsFirstRegistration(t *testing.T) {
346		root := t.TempDir()
