21	// symlinkFixtureRegistry is the registry content every linked-target fixture
22	// starts from.
23	const symlinkFixtureRegistry = `{"version":1,"batches":[{"batch":"OLD-1","product":"P-1","quantity":10,"unit":"kg"}]}`
24	
