52	// assertLinkIntact fails unless path is still a symbolic link storing exactly
53	// the link target text wantTarget.
54	func assertLinkIntact(t *testing.T, path, wantTarget string) {
55		t.Helper()
56		info, err := os.Lstat(path)
57		if err != nil {
58			t.Fatalf("the link must still exist: %v", err)
59		}
