72	// TestSaveThroughSymlinkWritesTarget covers the accepted link shapes —
73	// absolute target, relative target, target in a different directory — and
74	// checks the whole contract: the new content lands in the target file, the
75	// link survives as a link to the same target, the target keeps its
76	// permissions, and both paths read back the same records in order.
77	func TestSaveThroughSymlinkWritesTarget(t *testing.T) {
78		cases := []struct {
79			name       string
80			linkPath   func(root string) string
81			linkTarget func(root, targetPath string) string
82		}{
83			{
84				"absolute target, link beside target",
85				func(root string) string { return filepath.Join(root, "link.json") },
86				func(root, targetPath string) string { return targetPath },
87			},
88			{
89				"relative target, link beside target",
90				func(root string) string { return filepath.Join(root, "link.json") },
91				func(root, targetPath string) string { return "real-registry.json" },
92			},
93			{
94				"relative target, link in another directory",
95				func(root string) string { return filepath.Join(root, "links", "deep", "link.json") },
96				func(root, targetPath string) string {
97					return filepath.Join("..", "..", "real-registry.json")
98				},
99			},
100			{
101				"absolute target, link in another directory",
102				func(root string) string { return filepath.Join(root, "elsewhere", "link.json") },
