156	// A relative link target is resolved against the directory holding the link,
157	// never against the process working directory: saving through the link from
158	// an unrelated working directory must still update the one registry the link
159	// points at.
160	func TestSaveThroughRelativeSymlinkIgnoresWorkingDirectory(t *testing.T) {
161		root := t.TempDir()
162		targetPath := filepath.Join(root, "regdir", "registry.json")
163		linkPath := filepath.Join(root, "links", "registry-link.json")
164		setupLinkedRegistry(t, targetPath, linkPath, filepath.Join("..", "regdir", "registry.json"))
165	
166		// A decoy registry with the same relative path under the working
167		// directory: a save resolving the link against the working directory
168		// would land here instead of in the real target.
169		workDir := t.TempDir()
170		decoyPath := filepath.Join(workDir, "regdir", "registry.json")
171		writeRegistry(t, decoyPath, `{"version":1,"batches":[{"batch":"DECOY","product":"P","quantity":1,"unit":"kg"}]}`)
172		decoyBytes, err := os.ReadFile(decoyPath)
173		if err != nil {
174			t.Fatal(err)
175		}
176		t.Chdir(workDir)
177	
178		reg, existed, err := Load(linkPath)
179		if err != nil || !existed {
180			t.Fatalf("reading through the link must load the target: existed=%v err=%v", existed, err)
181		}
182		if _, err := Register(reg, Input{Batch: "NEW-1", Product: "P-9", Quantity: 5, Unit: "box"}); err != nil {
183			t.Fatal(err)
184		}
185		if err := Save(linkPath, reg); err != nil {
186			t.Fatalf("saving through the link must succeed: %v", err)
187		}
188	
189		loaded, existed, err := Load(targetPath)
190		if err != nil || !existed {
191			t.Fatalf("target must load: existed=%v err=%v", existed, err)
192		}
193		assertBatchesEqual(t, loaded.Batches, []Batch{
194			saveBatch("OLD-1", "P-1", 10, "kg"),
195			saveBatch("NEW-1", "P-9", 5, "box"),
196		})
197		after, err := os.ReadFile(decoyPath)
