207	// A link whose target does not exist is not a first registration: Load
208	// rejects it with an error naming the link path the user passed and the
209	// reason, and neither the target nor any stand-in file is created.
210	func TestLoadRejectsDanglingSymlink(t *testing.T) {
211		dir := t.TempDir()
212		linkPath := filepath.Join(dir, "link.json")
213		missingTarget := filepath.Join(dir, "missing.json")
214		if err := os.Symlink(missingTarget, linkPath); err != nil {
215			t.Fatal(err)
216		}
217	
218		reg, existed, err := Load(linkPath)
219		if err == nil {
220			t.Fatalf("Load must reject a dangling link, got reg=%+v existed=%v", reg, existed)
221		}
222		if !existed {
223			t.Errorf("a dangling link must not signal a fresh registry: existed=%v", existed)
224		}
225		msg := err.Error()
226		if !strings.Contains(msg, linkPath) {
227			t.Errorf("error %q must name the registry path the user passed", msg)
228		}
229		if !strings.Contains(msg, "symbolic link") || !strings.Contains(msg, "does not exist") {
230			t.Errorf("error %q must state the link target does not exist", msg)
231		}
232		assertLinkIntact(t, linkPath, missingTarget)
233		if _, statErr := os.Stat(missingTarget); !os.IsNotExist(statErr) {
234			t.Errorf("the missing target must not be created, stat err=%v", statErr)
235		}
