238	// Saving to a dangling link is rejected the same way: the error names the
239	// user's registry path, the link is left exactly as it was, the target is
240	// not created and no temporary file survives.
241	func TestSaveRejectsDanglingSymlink(t *testing.T) {
242		dir := t.TempDir()
243		linkPath := filepath.Join(dir, "link.json")
244		missingTarget := filepath.Join(dir, "missing.json")
245		if err := os.Symlink(missingTarget, linkPath); err != nil {
246			t.Fatal(err)
247		}
248	
249		reg := &Registry{Version: FormatVersion, Batches: []Batch{saveBatch("B1", "P1", 1, "kg")}}
250		err := Save(linkPath, reg)
251		if err == nil {
252			t.Fatal("Save must reject a dangling link")
253		}
254		msg := err.Error()
255		if !strings.Contains(msg, linkPath) {
256			t.Errorf("error %q must name the registry path the user passed", msg)
257		}
258		if !strings.Contains(msg, "symbolic link") {
259			t.Errorf("error %q must state the path is an unresolvable symbolic link", msg)
260		}
261		assertLinkIntact(t, linkPath, missingTarget)
262		if _, statErr := os.Stat(missingTarget); !os.IsNotExist(statErr) {
263			t.Errorf("the missing target must not be created, stat err=%v", statErr)
264		}
265		assertNoLeftoverTempFiles(t, dir)
266	}
