268	// A chain of links forming a loop has no determinable target: both Load and
269	// Save reject it with an error naming the user's registry path, and the
270	// links are left untouched.
271	func TestLoadAndSaveRejectSymlinkLoop(t *testing.T) {
272		dir := t.TempDir()
273		linkA := filepath.Join(dir, "a.json")
274		linkB := filepath.Join(dir, "b.json")
275		if err := os.Symlink(linkB, linkA); err != nil {
276			t.Fatal(err)
277		}
278		if err := os.Symlink(linkA, linkB); err != nil {
279			t.Fatal(err)
280		}
281	
282		_, _, loadErr := Load(linkA)
283		if loadErr == nil {
284			t.Fatal("Load must reject a link loop")
285		}
286		if !strings.Contains(loadErr.Error(), linkA) {
287			t.Errorf("load error %q must name the registry path the user passed", loadErr.Error())
288		}
289	
290		reg := &Registry{Version: FormatVersion, Batches: []Batch{saveBatch("B1", "P1", 1, "kg")}}
291		saveErr := Save(linkA, reg)
292		if saveErr == nil {
293			t.Fatal("Save must reject a link loop")
294		}
295		if !strings.Contains(saveErr.Error(), linkA) {
296			t.Errorf("save error %q must name the registry path the user passed", saveErr.Error())
297		}
298		assertLinkIntact(t, linkA, linkB)
299		assertLinkIntact(t, linkB, linkA)
300		assertNoLeftoverTempFiles(t, dir)
301	}
302	
303	// A save failing midway through a link keeps the linked registry exactly as
304	// it was: the target's bytes and modification time are untouched and the
305	// link survives, just as for a direct path.
306	func TestSaveFailureThroughSymlinkKeepsTargetIntact(t *testing.T) {
307		root := t.TempDir()
308		targetPath := filepath.Join(root, "real-registry.json")
309		linkPath := filepath.Join(root, "link.json")
310		originalBytes := setupLinkedRegistry(t, targetPath, linkPath, targetPath)
311		pinned := time.Date(2010, time.March, 4, 5, 6, 7, 0, time.UTC)
312		if err := os.Chtimes(targetPath, pinned, pinned); err != nil {
313			t.Fatal(err)
314		}
315	
316		cause := errors.New("injected write failure through link")
317		old := WriteTempContent
318		WriteTempContent = func(f *os.File, data []byte) (int, error) {
319			half := len(data) / 2
320			if _, err := f.Write(data[:half]); err != nil {
321				return 0, err
322			}
323			return half, cause
324		}
325		t.Cleanup(func() { WriteTempContent = old })
326	
327		reg, existed, err := Load(linkPath)
328		if err != nil || !existed {
329			t.Fatalf("fixture must load through the link: existed=%v err=%v", existed, err)
330		}
331		if _, err := Register(reg, Input{Batch: "NEW-1", Product: "P-9", Quantity: 5, Unit: "box"}); err != nil {
332			t.Fatal(err)
333		}
334		err = Save(linkPath, reg)
335		if err == nil {
336			t.Fatal("Save must report the injected failure")
337		}
338		if !errors.Is(err, cause) {
339			t.Errorf("error %v must carry the failure cause %v", err, cause)
340		}
341		if !strings.Contains(err.Error(), linkPath) {
342			t.Errorf("error %q must name the registry path the user passed %q", err.Error(), linkPath)
343		}
344	
345		info, err := os.Stat(targetPath)
346		if err != nil {
347			t.Fatal(err)
348		}
349		if !info.ModTime().Equal(pinned) {
350			t.Errorf("failed save touched the target's modification time: got %v, want %v", info.ModTime(), pinned)
351		}
352		after, err := os.ReadFile(targetPath)
353		if err != nil {
354			t.Fatal(err)
355		}
356		if !bytes.Equal(after, originalBytes) {
357			t.Fatalf("failed save changed the target bytes:\nbefore %s\nafter  %s", originalBytes, after)
358		}
359		assertLinkIntact(t, linkPath, targetPath)
360		assertNoLeftoverTempFiles(t, root)
361	}
