package batchreg

import (
	"bytes"
	"errors"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

// This file is the regression net for a registry reached through a DIRECTORY
// symbolic link followed by "..". With work/alias -> store/child, the user
// path work/alias/../batches.json names store/batches.json: the ".." leaves
// the directory the link really points at, not the directory holding the
// link. A save resolved lexically collapses alias/.. to work and writes next
// to the link; the rule under guard is that read and save resolve the path
// the same physical way the kernel does, so the new record lands in the real
// file, nothing is created next to the link (write access there is not even
// required), and an unrelated same-named file beside the link is untouched.

// dirLinkFixtureAt builds, under root,
//
//	root/
//	  store/
//	    child/                 (real directory)
//	    batches.json           (the real registry with one OLD-1 record)
//	  work/
//	    alias -> linkTarget    (directory link into store)
//	    batches.json           (an unrelated decoy registry)
//
// linkTarget is the exact text stored in the link. It returns the registry
// path a user would type (work/alias/../batches.json, built WITHOUT lexical
// cleaning so the link segment and the ".." both survive), the real registry
// path, the decoy path and the original real-registry bytes.
func dirLinkFixtureAt(t *testing.T, root, linkTarget string) (userPath, realPath, decoyPath, aliasPath string, original []byte) {
	t.Helper()
	storeDir := filepath.Join(root, "store")
	childDir := filepath.Join(storeDir, "child")
	if err := os.MkdirAll(childDir, 0o755); err != nil {
		t.Fatal(err)
	}
	workDir := filepath.Join(root, "work")
	if err := os.MkdirAll(workDir, 0o755); err != nil {
		t.Fatal(err)
	}
	realPath = filepath.Join(storeDir, "batches.json")
	writeRegistry(t, realPath, symlinkFixtureRegistry)
	decoyPath = filepath.Join(workDir, "batches.json")
	writeRegistry(t, decoyPath, `{"version":1,"batches":[{"batch":"DECOY","product":"P-0","quantity":1,"unit":"m"}]}`)
	aliasPath = filepath.Join(workDir, "alias")
	if err := os.Symlink(linkTarget, aliasPath); err != nil {
		t.Fatal(err)
	}
	// String concatenation on purpose: filepath.Join/Clean would collapse
	// "alias/.." to "work" and erase exactly the path shape under test.
	userPath = aliasPath + string(os.PathSeparator) + ".." + string(os.PathSeparator) + "batches.json"
	original, err := os.ReadFile(realPath)
	if err != nil {
		t.Fatal(err)
	}
	return userPath, realPath, decoyPath, aliasPath, original
}

// dirLinkFixture builds the layout in a fresh temporary directory.
func dirLinkFixture(t *testing.T, linkTarget string) (root, userPath, realPath, decoyPath, aliasPath string, original []byte) {
	t.Helper()
	root = t.TempDir()
	userPath, realPath, decoyPath, aliasPath, original = dirLinkFixtureAt(t, root, linkTarget)
	return root, userPath, realPath, decoyPath, aliasPath, original
}

// pinFile stamps a past mtime on path so any rewrite is observable.
func pinFile(t *testing.T, path string) time.Time {
	t.Helper()
	pinned := time.Date(2008, time.August, 9, 10, 11, 12, 0, time.UTC)
	if err := os.Chtimes(path, pinned, pinned); err != nil {
		t.Fatal(err)
	}
	return pinned
}

// Reading the registry through work/alias/../batches.json sees the real
// store/batches.json, and a save of a newly registered batch appends to that
// real file: old record first, new record last, visible through the user path
// and the real path alike. The decoy beside the link keeps its bytes, the
// link keeps its target text, and no temporary file survives anywhere.
func TestSaveThroughDirectorySymlinkDotDotLandsInRealFile(t *testing.T) {
	cases := []struct {
		name   string
		target func(root string) string
	}{
		{"relative target", func(root string) string { return filepath.Join("..", "store", "child") }},
		{"absolute target", func(root string) string { return filepath.Join(root, "store", "child") }},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			root := t.TempDir()
			userPath, realPath, decoyPath, aliasPath, original := dirLinkFixtureAt(t, root, tc.target(root))

			decoyBytes, err := os.ReadFile(decoyPath)
			if err != nil {
				t.Fatal(err)
			}
			realPinned := pinFile(t, realPath)
			decoyPinned := pinFile(t, decoyPath)

			reg, existed, err := Load(userPath)
			if err != nil || !existed {
				t.Fatalf("reading through the directory link must load the real registry: existed=%v err=%v", existed, err)
			}
			if len(reg.Batches) != 1 || reg.Batches[0].Batch != "OLD-1" {
				t.Fatalf("the user path must see the real records, got %+v", reg.Batches)
			}
			if _, err := Register(reg, Input{Batch: "NEW-1", Product: "P-9", Quantity: 5, Unit: "box"}); err != nil {
				t.Fatal(err)
			}
			if err := Save(userPath, reg); err != nil {
				t.Fatalf("saving through the directory link must succeed: %v", err)
			}

			want := []Batch{
				saveBatch("OLD-1", "P-1", 10, "kg"),
				saveBatch("NEW-1", "P-9", 5, "box"),
			}
			assertBatchesEqual(t, mustLoad(t, realPath).Batches, want)
			assertBatchesEqual(t, mustLoad(t, userPath).Batches, want)

			// The real file is the one rewritten: its pinned mtime must move.
			if info, err := os.Stat(realPath); err != nil {
				t.Fatal(err)
			} else if info.ModTime().Equal(realPinned) {
				t.Fatal("the real registry was not rewritten; the save landed elsewhere")
			}
			// The decoy beside the link is unrelated: bytes and mtime intact.
			after, err := os.ReadFile(decoyPath)
			if err != nil {
				t.Fatal(err)
			}
			if !bytes.Equal(after, decoyBytes) {
				t.Fatalf("the decoy beside the link changed:\nbefore %s\nafter  %s", decoyBytes, after)
			}
			if info, err := os.Stat(decoyPath); err != nil {
				t.Fatal(err)
			} else if !info.ModTime().Equal(decoyPinned) {
				t.Fatalf("the decoy mtime moved: got %v want %v", info.ModTime(), decoyPinned)
			}
			// Nothing was written next to the link: only the link and the
			// decoy may exist there.
			entries, err := os.ReadDir(filepath.Dir(aliasPath))
			if err != nil {
				t.Fatal(err)
			}
			for _, e := range entries {
				if e.Name() != "alias" && e.Name() != "batches.json" {
					t.Fatalf("save created %q next to the directory link", e.Name())
				}
			}
			assertLinkIntact(t, aliasPath, tc.target(root))
			assertNoLeftoverTempFiles(t, root)
			_ = original
		})
	}
}

// mustLoad loads path or fails the test; it keeps the fixtures readable.
func mustLoad(t *testing.T, path string) *Registry {
	t.Helper()
	reg, existed, err := Load(path)
	if err != nil || !existed {
		t.Fatalf("Load(%q): existed=%v err=%v", path, existed, err)
	}
	return reg
}

// A save through work/alias/../batches.json must not require write access in
// work: making the link's own directory read-and-execute-only leaves the save
// working, because the temporary file is prepared in the real target
// directory. Skipped under root, which bypasses directory permission bits.
func TestSaveThroughDirectorySymlinkDotDotNeedsNoWriteInLinkDirectory(t *testing.T) {
	if os.Geteuid() == 0 {
		t.Skip("root bypasses directory write permission bits")
	}
	root, userPath, realPath, decoyPath, aliasPath, _ := dirLinkFixture(t, filepath.Join("..", "store", "child"))
	workDir := filepath.Dir(aliasPath)
	if err := os.Chmod(workDir, 0o555); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = os.Chmod(workDir, 0o755) })

	reg := mustLoad(t, userPath)
	if _, err := Register(reg, Input{Batch: "NEW-1", Product: "P-9", Quantity: 5, Unit: "box"}); err != nil {
		t.Fatal(err)
	}
	if err := Save(userPath, reg); err != nil {
		t.Fatalf("a read-only link directory must not block the save: %v", err)
	}
	assertBatchesEqual(t, mustLoad(t, realPath).Batches, []Batch{
		saveBatch("OLD-1", "P-1", 10, "kg"),
		saveBatch("NEW-1", "P-9", 5, "box"),
	})
	assertBatchesEqual(t, mustLoad(t, userPath).Batches, mustLoad(t, realPath).Batches)
	assertLinkIntact(t, aliasPath, filepath.Join("..", "store", "child"))
	assertNoLeftoverTempFiles(t, root)
	// The read-only directory must contain only what it started with.
	entries, err := os.ReadDir(workDir)
	if err != nil {
		t.Fatal(err)
	}
	for _, e := range entries {
		if e.Name() != "alias" && e.Name() != "batches.json" {
			t.Fatalf("save created %q in the read-only link directory", e.Name())
		}
	}
	_ = decoyPath
}

// The atomic rename — the step that actually chooses which file is replaced —
// must target the real store/batches.json, never the same-named decoy beside
// the link. This works under every account, root included, because it
// observes Save's own resolved target.
func TestSaveThroughDirectorySymlinkDotDotRenamesRealFile(t *testing.T) {
	root, userPath, realPath, decoyPath, aliasPath, original := dirLinkFixture(t, filepath.Join("..", "store", "child"))
	pinned := pinFile(t, realPath)
	decoyBytes, err := os.ReadFile(decoyPath)
	if err != nil {
		t.Fatal(err)
	}

	cause := errors.New("injected replacement refusal through directory link")
	var renamedTo string
	old := RenameTempFile
	RenameTempFile = func(oldpath, newpath string) error {
		renamedTo = newpath
		return cause
	}
	t.Cleanup(func() { RenameTempFile = old })

	reg := mustLoad(t, userPath)
	if _, err := Register(reg, Input{Batch: "NEW-1", Product: "P-9", Quantity: 5, Unit: "box"}); err != nil {
		t.Fatal(err)
	}
	err = Save(userPath, reg)
	if err == nil {
		t.Fatal("Save must surface the injected rename failure")
	}
	if !errors.Is(err, cause) {
		t.Errorf("error %v must carry the cause %v", err, cause)
	}
	if !strings.Contains(err.Error(), userPath) {
		t.Errorf("error %q must name the user-supplied path %q", err.Error(), userPath)
	}
	if renamedTo != realPath {
		t.Fatalf("rename target = %q, want the real registry %q", renamedTo, realPath)
	}
	if renamedTo == decoyPath {
		t.Fatal("the save must never rename onto the decoy beside the link")
	}

	// Failed save: real registry keeps bytes and mtime, decoy untouched, no
	// temporary file survives, the link is unchanged.
	if info, err := os.Stat(realPath); err != nil {
		t.Fatal(err)
	} else if !info.ModTime().Equal(pinned) {
		t.Fatalf("failed save moved the real registry mtime: got %v want %v", info.ModTime(), pinned)
	}
	after, err := os.ReadFile(realPath)
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(after, original) {
		t.Fatalf("failed save changed the real registry bytes:\nbefore %s\nafter  %s", original, after)
	}
	decoyAfter, err := os.ReadFile(decoyPath)
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(decoyAfter, decoyBytes) {
		t.Fatalf("failed save changed the decoy bytes:\nbefore %s\nafter  %s", decoyBytes, decoyAfter)
	}
	assertLinkIntact(t, aliasPath, filepath.Join("..", "store", "child"))
	assertNoLeftoverTempFiles(t, root)
}

// A first registration addressed through work/alias/../fresh.json creates the
// file in the real store directory, not next to the link.
func TestSaveNewFileThroughDirectorySymlinkDotDotLandsInRealDirectory(t *testing.T) {
	root, _, _, decoyPath, aliasPath, _ := dirLinkFixture(t, filepath.Join("..", "store", "child"))
	userPath := aliasPath + string(os.PathSeparator) + ".." + string(os.PathSeparator) + "fresh.json"
	realFresh := filepath.Join(root, "store", "fresh.json")
	linkDirFresh := filepath.Join(root, "work", "fresh.json")

	reg := &Registry{Version: FormatVersion, Batches: []Batch{saveBatch("B1", "P1", 1, "kg")}}
	if err := Save(userPath, reg); err != nil {
		t.Fatalf("first registration through the directory link must save: %v", err)
	}
	if _, err := os.Stat(realFresh); err != nil {
		t.Fatalf("the new registry must be created in the real directory: %v", err)
	}
	if _, err := os.Stat(linkDirFresh); !os.IsNotExist(err) {
		t.Fatalf("no file may be created next to the link, stat err=%v", err)
	}
	assertBatchesEqual(t, mustLoad(t, userPath).Batches, mustLoad(t, realFresh).Batches)
	assertLinkIntact(t, aliasPath, filepath.Join("..", "store", "child"))
	assertNoLeftoverTempFiles(t, root)
	_ = decoyPath
}

// When the REAL target directory is not writable, the save is rejected: the
// error names the user-supplied path (not the resolved internal one) and the
// reason, the real registry keeps bytes and mtime, the decoy and link are
// untouched and no temporary file remains. Permission bits are root-bypassed,
// so the unwritable-directory case is skipped for root and covered portably by
// the injected rename test above.
func TestSaveThroughDirectorySymlinkDotDotFailsWhenRealDirectoryUnwritable(t *testing.T) {
	if os.Geteuid() == 0 {
		t.Skip("root bypasses directory write permission bits")
	}
	root, userPath, realPath, decoyPath, aliasPath, original := dirLinkFixture(t, filepath.Join("..", "store", "child"))
	storeDir := filepath.Join(root, "store")
	pinned := pinFile(t, realPath)
	decoyBytes, err := os.ReadFile(decoyPath)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.Chmod(storeDir, 0o555); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = os.Chmod(storeDir, 0o755) })

	reg := mustLoad(t, userPath)
	if _, err := Register(reg, Input{Batch: "NEW-1", Product: "P-9", Quantity: 5, Unit: "box"}); err != nil {
		t.Fatal(err)
	}
	err = Save(userPath, reg)
	if err == nil {
		t.Fatal("a save into an unwritable real target directory must fail")
	}
	msg := err.Error()
	if !strings.Contains(msg, userPath) {
		t.Errorf("error %q must name the user-supplied registry path %q", msg, userPath)
	}
	if !strings.Contains(msg, "permission denied") {
		t.Errorf("error %q must state the concrete reason", msg)
	}
	if info, err := os.Stat(realPath); err != nil {
		t.Fatal(err)
	} else if !info.ModTime().Equal(pinned) {
		t.Fatalf("failed save moved the real registry mtime: got %v want %v", info.ModTime(), pinned)
	}
	after, err := os.ReadFile(realPath)
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(after, original) {
		t.Fatalf("failed save changed the real registry bytes:\nbefore %s\nafter  %s", original, after)
	}
	decoyAfter, err := os.ReadFile(decoyPath)
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(decoyAfter, decoyBytes) {
		t.Fatalf("the decoy beside the link changed:\nbefore %s\nafter  %s", decoyBytes, decoyAfter)
	}
	assertLinkIntact(t, aliasPath, filepath.Join("..", "store", "child"))
	assertNoLeftoverTempFiles(t, root)
}

// A dangling directory link followed by ".." is not a first registration: the
// save rejects it as an unresolvable symbolic link instead of dropping a file
// next to the link, and nothing is created anywhere.
func TestSaveThroughDanglingDirectorySymlinkDotDotRejected(t *testing.T) {
	root := t.TempDir()
	workDir := filepath.Join(root, "work")
	if err := os.MkdirAll(workDir, 0o755); err != nil {
		t.Fatal(err)
	}
	// A decoy same-named file beside the link is what a lexical save would
	// overwrite; it must survive byte-for-byte.
	decoyPath := filepath.Join(workDir, "batches.json")
	decoy := `{"version":1,"batches":[{"batch":"DECOY","product":"P","quantity":1,"unit":"kg"}]}`
	writeRegistry(t, decoyPath, decoy)
	aliasPath := filepath.Join(workDir, "alias")
	missingDir := filepath.Join("..", "store", "missing-child")
	if err := os.Symlink(missingDir, aliasPath); err != nil {
		t.Fatal(err)
	}
	userPath := aliasPath + string(os.PathSeparator) + ".." + string(os.PathSeparator) + "batches.json"
	pinned := pinFile(t, decoyPath)

	reg := &Registry{Version: FormatVersion, Batches: []Batch{saveBatch("B1", "P1", 1, "kg")}}
	err := Save(userPath, reg)
	if err == nil {
		t.Fatal("a save through a dangling directory link must be rejected")
	}
	msg := err.Error()
	if !strings.Contains(msg, userPath) {
		t.Errorf("error %q must name the user-supplied path %q", msg, userPath)
	}
	if !strings.Contains(msg, "symbolic link") {
		t.Errorf("error %q must state the path is an unresolvable symbolic link", msg)
	}
	assertLinkIntact(t, aliasPath, missingDir)
	after, err := os.ReadFile(decoyPath)
	if err != nil {
		t.Fatal(err)
	}
	if string(after) != decoy {
		t.Fatalf("the lexical-resolution decoy was overwritten:\nwant %s\ngot  %s", decoy, after)
	}
	if info, err := os.Stat(decoyPath); err != nil {
		t.Fatal(err)
	} else if !info.ModTime().Equal(pinned) {
		t.Fatalf("the decoy mtime moved: got %v want %v", info.ModTime(), pinned)
	}
	assertNoLeftoverTempFiles(t, root)
}

// A loop of directory links reached with ".." likewise rejects the save
// without creating anything next to either link.
func TestSaveThroughDirectorySymlinkLoopDotDotRejected(t *testing.T) {
	root := t.TempDir()
	workDir := filepath.Join(root, "work")
	if err := os.MkdirAll(workDir, 0o755); err != nil {
		t.Fatal(err)
	}
	linkA := filepath.Join(workDir, "a")
	linkB := filepath.Join(workDir, "b")
	if err := os.Symlink("b", linkA); err != nil {
		t.Fatal(err)
	}
	if err := os.Symlink("a", linkB); err != nil {
		t.Fatal(err)
	}
	userPath := linkA + string(os.PathSeparator) + ".." + string(os.PathSeparator) + "batches.json"

	reg := &Registry{Version: FormatVersion, Batches: []Batch{saveBatch("B1", "P1", 1, "kg")}}
	err := Save(userPath, reg)
	if err == nil {
		t.Fatal("a save through a directory-link loop must be rejected")
	}
	if !strings.Contains(err.Error(), userPath) {
		t.Errorf("error %q must name the user-supplied path %q", err.Error(), userPath)
	}
	assertLinkIntact(t, linkA, "b")
	assertLinkIntact(t, linkB, "a")
	assertNoLeftoverTempFiles(t, root)
	if entries, err := os.ReadDir(workDir); err != nil {
		t.Fatal(err)
	} else if len(entries) != 2 {
		t.Fatalf("nothing may be created next to the looping links, got %v", entries)
	}
}

package batchreg

import (
	"bytes"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

// This file is the regression net for the missing-directory-then-".." escape.
// With store/batches.json registered and store/missing absent, the user path
// store/missing/../batches.json does not name any file the way the kernel
// resolves names: the ".." cannot step out of "missing" while "missing" does
// not exist. A save that collapses the path lexically (or first creates
// "missing") would reach store/batches.json and overwrite the registry with
// just the new batch. The rule under guard is that Save refuses such a path
// before creating anything: the error names the user-supplied path and the
// reason, an existing same-named file keeps its bytes and modification time,
// no missing directory, registry file or temporary file appears, and the
// caller's submitted batches keep their content and order. Relative paths and
// the absolute paths with the same directory structure behave identically.
//
// Ordinary creation is preserved: a path whose parent merely does not exist
// without climbing back (store/new/batches.json) still creates the directory
// and the registry, and a ".." after a directory that really exists keeps
// resolving by real directory relations — including a directory symlink,
// covered in batchreg_dirsymlink_dotdot_test.go.

// missingDotDotRegistryJSON is the one-record registry the fixtures start
// with; a successful escape would leave only the new batch behind.
const missingDotDotRegistryJSON = `{"version":1,"batches":[{"batch":"OLD","product":"P-1","quantity":10,"unit":"kg"}]}`

// missingEscapeFixture builds
//
//	root/
//	  store/
//	    batches.json   (registry holding OLD, mtime pinned)
//
// with no store/missing directory, and returns root and the registry path.
func missingEscapeFixture(t *testing.T) (root, registry string, original []byte, pinned time.Time) {
	t.Helper()
	root = t.TempDir()
	storeDir := filepath.Join(root, "store")
	if err := os.MkdirAll(storeDir, 0o755); err != nil {
		t.Fatal(err)
	}
	registry = filepath.Join(storeDir, "batches.json")
	writeRegistry(t, registry, missingDotDotRegistryJSON)
	pinned = pinFile(t, registry)
	original, err := os.ReadFile(registry)
	if err != nil {
		t.Fatal(err)
	}
	return root, registry, original, pinned
}

// assertMissingDirAbsent fails if the missing directory named in the escape
// path was brought into existence by the rejected save.
func assertMissingDirAbsent(t *testing.T, root, rel string) {
	t.Helper()
	if _, err := os.Lstat(filepath.Join(root, rel)); !os.IsNotExist(err) {
		t.Fatalf("the rejected save must not create %s, stat err=%v", rel, err)
	}
}

// rawJoin joins components with the OS separator WITHOUT lexical cleaning, so
// the deliberately unresolvable "missing/.." segment reaches Save exactly as
// a user would type it (filepath.Join/Clean would erase it).
func rawJoin(parts ...string) string {
	return strings.Join(parts, string(os.PathSeparator))
}

// assertEscapeRejected checks the shared error contract: a non-nil error that
// quotes the exact user path, names the missing directory and says the path
// climbs back with "..".
func assertEscapeRejected(t *testing.T, err error, userPath, missingName string) {
	t.Helper()
	if err == nil {
		t.Fatal("Save must reject a path that descends into a missing directory and climbs back with \"..\"")
	}
	msg := err.Error()
	for _, want := range []string{
		userPath,
		"does not exist",
		"..",
		"not written",
	} {
		if !strings.Contains(msg, want) {
			t.Errorf("error %q must mention %q", msg, want)
		}
	}
	if missingName != "" && !strings.Contains(msg, missingName) {
		t.Errorf("error %q must name the missing directory %q", msg, missingName)
	}
}

// Saving a legal registry addressed through store/missing/../batches.json
// must fail while store/batches.json keeps OLD: exact bytes, pinned mtime, no
// store/missing directory, no replacement file anywhere and no temporary file.
// The submitted batches and their order are untouched.
func TestSaveRejectsMissingDirDotDotOverExistingRegistry(t *testing.T) {
	root, registry, original, pinned := missingEscapeFixture(t)
	userPath := rawJoin(root, "store", "missing", "..", "batches.json")

	submitted := []Batch{saveBatch("NEW", "P-9", 5, "box")}
	reg := &Registry{Version: FormatVersion, Batches: append([]Batch(nil), submitted...)}
	err := Save(userPath, reg)

	assertEscapeRejected(t, err, userPath, "missing")
	after, statErr := os.ReadFile(registry)
	if statErr != nil {
		t.Fatalf("the existing registry must still be present: %v", statErr)
	}
	if !bytes.Equal(after, original) {
		t.Fatalf("the escape overwrote the existing registry:\nbefore %s\nafter  %s", original, after)
	}
	if info, err := os.Stat(registry); err != nil {
		t.Fatal(err)
	} else if !info.ModTime().Equal(pinned) {
		t.Fatalf("the escape moved the registry mtime: got %v want %v", info.ModTime(), pinned)
	}
	assertMissingDirAbsent(t, root, filepath.Join("store", "missing"))
	assertNoLeftoverTempFiles(t, root)
	assertBatchesEqual(t, reg.Batches, submitted)
	// The surviving registry still reads back with its single OLD record.
	assertBatchesEqual(t, mustLoad(t, registry).Batches,
		[]Batch{saveBatch("OLD", "P-1", 10, "kg")})
}

// Even with no same-named file at the lexically cleaned location, the path is
// not a place to create a fresh registry: the save is rejected and neither
// the file nor the missing directory appears.
func TestSaveRejectsMissingDirDotDotWithoutExistingFileCreatesNothing(t *testing.T) {
	root := t.TempDir()
	storeDir := filepath.Join(root, "store")
	if err := os.MkdirAll(storeDir, 0o755); err != nil {
		t.Fatal(err)
	}
	userPath := rawJoin(root, "store", "missing", "..", "fresh.json")

	reg := &Registry{Version: FormatVersion, Batches: []Batch{saveBatch("NEW", "P-9", 5, "box")}}
	err := Save(userPath, reg)

	assertEscapeRejected(t, err, userPath, "missing")
	if _, statErr := os.Lstat(filepath.Join(storeDir, "fresh.json")); !os.IsNotExist(statErr) {
		t.Fatalf("no registry may be created at the cleaned name, stat err=%v", statErr)
	}
	assertMissingDirAbsent(t, root, filepath.Join("store", "missing"))
	if entries, err := os.ReadDir(storeDir); err != nil {
		t.Fatal(err)
	} else if len(entries) != 0 {
		t.Fatalf("the rejected save left entries in store: %v", entries)
	}
	assertNoLeftoverTempFiles(t, root)
}

// A path that climbs past the missing directory more than once
// (store/missing/../../root-file) is rejected just the same and creates
// nothing outside store either.
func TestSaveRejectsMissingDirDotDotClimbingPastParent(t *testing.T) {
	root := t.TempDir()
	storeDir := filepath.Join(root, "store")
	if err := os.MkdirAll(storeDir, 0o755); err != nil {
		t.Fatal(err)
	}
	userPath := rawJoin(root, "store", "missing", "..", "..", "outside.json")

	reg := &Registry{Version: FormatVersion, Batches: []Batch{saveBatch("NEW", "P-9", 5, "box")}}
	err := Save(userPath, reg)

	assertEscapeRejected(t, err, userPath, "missing")
	for _, p := range []string{
		filepath.Join(root, "outside.json"),
		filepath.Join(storeDir, "outside.json"),
		filepath.Join(storeDir, "missing"),
	} {
		if _, statErr := os.Lstat(p); !os.IsNotExist(statErr) {
			t.Fatalf("the rejected save must not create %s, stat err=%v", p, statErr)
		}
	}
	assertNoLeftoverTempFiles(t, root)
}

// A relative registry path and the absolute path spelling the same directory
// structure must give the same verdict and leave the same files behind.
func TestSaveMissingDirDotDotRelativeAndAbsoluteAgree(t *testing.T) {
	setup := func(t *testing.T) string {
		t.Helper()
		root := t.TempDir()
		writeRegistry(t, filepath.Join(root, "store", "batches.json"), missingDotDotRegistryJSON)
		t.Chdir(root)
		return root
	}

	t.Run("relative", func(t *testing.T) {
		root := setup(t)
		userPath := rawJoin("store", "missing", "..", "batches.json")
		reg := &Registry{Version: FormatVersion, Batches: []Batch{saveBatch("NEW", "P-9", 5, "box")}}
		err := Save(userPath, reg)
		assertEscapeRejected(t, err, userPath, "missing")
		assertMissingDirAbsent(t, root, filepath.Join("store", "missing"))
		assertBatchesEqual(t, mustLoad(t, filepath.Join(root, "store", "batches.json")).Batches,
			[]Batch{saveBatch("OLD", "P-1", 10, "kg")})
	})
	t.Run("absolute", func(t *testing.T) {
		root := setup(t)
		userPath := rawJoin(root, "store", "missing", "..", "batches.json")
		reg := &Registry{Version: FormatVersion, Batches: []Batch{saveBatch("NEW", "P-9", 5, "box")}}
		err := Save(userPath, reg)
		assertEscapeRejected(t, err, userPath, "missing")
		assertMissingDirAbsent(t, root, filepath.Join("store", "missing"))
		assertBatchesEqual(t, mustLoad(t, filepath.Join(root, "store", "batches.json")).Batches,
			[]Batch{saveBatch("OLD", "P-1", 10, "kg")})
	})
}

// A bare relative path whose first component is the missing directory
// ("missing/../b.json" run from a directory without "missing") is refused too:
// the no-separator termination must not let the shape escape the check.
func TestSaveRejectsBareRelativeMissingDirDotDot(t *testing.T) {
	root := t.TempDir()
	t.Chdir(root)
	userPath := rawJoin("missing", "..", "fresh.json")

	reg := &Registry{Version: FormatVersion, Batches: []Batch{saveBatch("NEW", "P-9", 5, "box")}}
	err := Save(userPath, reg)

	assertEscapeRejected(t, err, userPath, "missing")
	assertMissingDirAbsent(t, root, "missing")
	if _, statErr := os.Lstat(filepath.Join(root, "fresh.json")); !os.IsNotExist(statErr) {
		t.Fatalf("no file may be created at the cleaned name, stat err=%v", statErr)
	}
	assertNoLeftoverTempFiles(t, root)
}

// Normal first registration is preserved: creating store/new/batches.json,
// whose parent does not exist and which never climbs back, still makes the
// directory and writes the registry.
func TestSaveCreatesNewDirectoriesWithoutDotDot(t *testing.T) {
	root := t.TempDir()
	userPath := filepath.Join(root, "store", "new", "batches.json")

	want := []Batch{saveBatch("NEW", "P-9", 5, "box")}
	reg := &Registry{Version: FormatVersion, Batches: want}
	if err := Save(userPath, reg); err != nil {
		t.Fatalf("a first registration in a new directory must succeed: %v", err)
	}
	assertBatchesEqual(t, mustLoad(t, userPath).Batches, want)
	assertNoLeftoverTempFiles(t, root)
}

// A ".." after a directory that really exists keeps resolving by real
// directory relations and must not be mistaken for the rejected shape.
func TestSaveAllowsDotDotAfterExistingDirectory(t *testing.T) {
	root := t.TempDir()
	registry := filepath.Join(root, "store", "batches.json")
	writeRegistry(t, registry, missingDotDotRegistryJSON)
	// store/child is a genuine directory; store/child/../batches.json is the
	// real registry.
	if err := os.MkdirAll(filepath.Join(root, "store", "child"), 0o755); err != nil {
		t.Fatal(err)
	}
	userPath := filepath.Join(root, "store", "child", "..", "batches.json")

	reg := mustLoad(t, userPath)
	if _, err := Register(reg, Input{Batch: "NEW", Product: "P-9", Quantity: 5, Unit: "box"}); err != nil {
		t.Fatal(err)
	}
	if err := Save(userPath, reg); err != nil {
		t.Fatalf("a \"..\" after a real directory must resolve and save: %v", err)
	}
	assertBatchesEqual(t, mustLoad(t, registry).Batches, []Batch{
		saveBatch("OLD", "P-1", 10, "kg"),
		saveBatch("NEW", "P-9", 5, "box"),
	})
	assertNoLeftoverTempFiles(t, root)

	// A missing directory that appears only AFTER a physical ".." is ordinary
	// new-directory creation: store/../store/newer/batches.json.
	newer := filepath.Join(root, "store", "newer", "batches.json")
	userPath2 := filepath.Join(root, "store", "..", "store", "newer", "batches.json")
	reg2 := &Registry{Version: FormatVersion, Batches: []Batch{saveBatch("B1", "P1", 1, "kg")}}
	if err := Save(userPath2, reg2); err != nil {
		t.Fatalf("a missing directory after a physical \"..\" must be creatable: %v", err)
	}
	assertBatchesEqual(t, mustLoad(t, newer).Batches, []Batch{saveBatch("B1", "P1", 1, "kg")})
}

// A "." interspersed in the not-yet-existing tail does not launder the escape:
// store/./missing/../fresh.json is still rejected, while store/./child/.. with
// child real is an ordinary save.
func TestSaveDotSegmentDoesNotLaunderMissingDirDotDot(t *testing.T) {
	root := t.TempDir()
	if err := os.MkdirAll(filepath.Join(root, "store"), 0o755); err != nil {
		t.Fatal(err)
	}
	// Assemble with separators directly; filepath.Join would keep the "." but
	// be explicit about the raw shape under test.
	userPath := filepath.Join(root, "store") + string(os.PathSeparator) +
		"." + string(os.PathSeparator) + "missing" + string(os.PathSeparator) +
		".." + string(os.PathSeparator) + "fresh.json"

	reg := &Registry{Version: FormatVersion, Batches: []Batch{saveBatch("NEW", "P-9", 5, "box")}}
	err := Save(userPath, reg)

	assertEscapeRejected(t, err, userPath, "missing")
	assertMissingDirAbsent(t, root, filepath.Join("store", "missing"))
	if _, statErr := os.Lstat(filepath.Join(root, "store", "fresh.json")); !os.IsNotExist(statErr) {
		t.Fatalf("no file may be created at the cleaned name, stat err=%v", statErr)
	}
	assertNoLeftoverTempFiles(t, root)
}

// Command govflow is the DAO 治理提案与执行平台 entry point.
package main

import (
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"strings"

	"github.com/gzhysuiioo/govflow-proposals/govflow"
	"github.com/gzhysuiioo/govflow-proposals/govflow/batchreg"
)

const batchRegisterUsage = `usage: govflow batch-register --registry FILE --batch ID --product ID --quantity N --unit UNIT
run 'govflow help' for the full description and the registry file format.
`

const batchImportUsage = `usage: govflow batch-import --registry FILE --input FILE
run 'govflow help' for the full description and the registry file format.
`

func main() {
	if err := run(os.Args[1:]); err != nil {
		fmt.Fprintln(os.Stderr, "govflow:", err)
		var ue *usageError
		if errors.As(err, &ue) {
			fmt.Fprint(os.Stderr, ue.usage)
		}
		os.Exit(1)
	}
}

type usageError struct {
	msg   string
	usage string
}

func (e *usageError) Error() string { return e.msg }

func run(args []string) error {
	command := "demo"
	if len(args) > 0 {
		command = args[0]
	}
	switch command {
	case "demo":
		runDemo()
		return nil
	case "version":
		fmt.Println("govflow 0.1.0")
		return nil
	case "help", "-h", "--help":
		fmt.Print(rootUsage())
		return nil
	case "batch-register":
		return runBatchRegister(args[1:], os.Stdout)
	case "batch-import":
		return runBatchImport(args[1:], os.Stdout)
	default:
		fmt.Fprintf(os.Stderr, "unknown command %q\n", command)
		fmt.Fprint(os.Stderr, rootUsage())
		os.Exit(2)
		return nil
	}
}

func rootUsage() string {
	return `govflow - DAO 治理提案与执行平台 / supply-chain batch registry

usage:
  govflow                                  run the built-in demo (default)
  govflow demo                             run the built-in demo
  govflow version                          print the version
  govflow help                             show this help
  govflow batch-register --registry FILE \
      --batch ID --product ID --quantity N --unit UNIT
                                           register one supply-chain batch in
                                           the registry FILE (see below)
  govflow batch-import --registry FILE --input FILE
                                           register every batch listed in the
                                           JSON manifest FILE into the registry
                                           FILE, all records or none

batch-register flags:
  --registry FILE   registry file to read and write (required)
  --batch ID        batch number; unique within one registry file (required)
  --product ID      product number the batch belongs to (required)
  --quantity N      positive decimal integer, digits 0-9 only, leading
                    zeros allowed, max 9223372036854775807 (required)
  --unit UNIT       measurement unit, e.g. kg or box (required)

batch-import flags:
  --registry FILE   registry file to read and write (required)
  --input FILE      read-only JSON manifest (required); a non-empty array of
                    objects carrying exactly batch, product, quantity and
                    unit. Text fields must be non-blank after trimming, and
                    quantity must be a JSON integer from 1 to
                    9223372036854775807 (no strings, fractions or exponents)

The whole manifest is rejected unless every record can be registered or
confirmed as a duplicate: a batch id already stored or seen earlier in the
manifest must match product, quantity and unit exactly, or none of the new
batches are saved and the error names the 1-based record position, the batch
id and the mismatching field(s). On success stdout contains one JSON object
whose results array keeps manifest order, each entry carrying the normalized
four fields plus status "created" or "duplicate"; new batches are appended
in first-occurrence order and an all-duplicate manifest leaves the registry
file byte-for-byte untouched.

Batch, product and unit values have leading and trailing whitespace removed
and must be non-empty afterwards; interior characters and casing are kept
("B1" and "b1" are different batches). One invocation registers one batch.

Batch, product and unit must be valid UTF-8 text in every source: command
line flags, import manifest records and stored registry records. A value
containing malformed UTF-8 bytes (or a JSON string holding a lone surrogate
escape such as "\ud800") is rejected and never replaced with the U+FFFD
replacement character, so distinct inputs cannot collapse onto one batch
id; the error names the parameter, or the manifest/registry file with the
1-based record position and field (plus the batch id only when it is itself
valid and unambiguous). The same rule applies to field NAMES in the JSON
files: a name with malformed bytes or a lone surrogate escape rejects the
whole operation with an invalid-field-name error naming the file (plus the
1-based record position, and the batch id when unambiguous, for record
level problems) — it is never reported as an unknown field under the
substituted text. A genuinely entered U+FFFD character is ordinary
text, non-ASCII ids (Chinese text, emoji, ...) are welcome, and a JSON
escape means the same text as the character written directly.

On success stdout contains a single JSON object, e.g.
  {"batch":"B-001","product":"P-7","quantity":120,"unit":"kg","status":"created"}
status is "created" for a new record and "duplicate" when the same batch was
already registered with the identical product, quantity and unit; a duplicate
does not rewrite the file and is safe to retry. Registering an existing batch
with any different field is rejected; the error names the batch and the
mismatching field(s) and no record is changed.

registry file format (UTF-8 JSON, human-inspectable):
  {
    "version": 1,
    "batches": [
      {"batch": "B-001", "product": "P-7", "quantity": 120, "unit": "kg"}
    ]
  }
A missing file is created on first registration, and a registry whose parent
directory does not yet exist is created together with that directory, as long
as the path never climbs back out of a directory it just descended into. The
registry path must name a FILE: a path ending in one or more path separators
("store/new.json/") or whose final component is "." or ".." ("store/new/.",
"store/new/..") spells a DIRECTORY location and is rejected outright, no
matter whether the location does not exist yet, already is a directory, or has
a regular file directly beneath the spelled name. The trailing directory
marker is never stripped to save a sibling plain file — "store/new.json/"
would otherwise create "store/new.json" and "store/new/." the plain file
"store/new", neither readable back through the path the user gave — no
missing parent directory is created, no registry or temporary file is left at
the stripped name, and an existing file, directory or symbolic link is never
replaced. The error quotes the registry path exactly as passed and states
that the target must be a file while this path denotes a directory; a "." or
".." in a MIDDLE path component ("store/./b.json") keeps resolving by the
ordinary rules.
A path that first passes through a directory that does not exist and then steps
back with ".." — store/missing/../batches.json while store/missing is absent —
names no file the way the filesystem resolves names and is rejected outright:
the missing directory is not created to make the path valid, the name left
after dropping the missing segment is not written (an existing registry there
is never overwritten), and no temporary file remains. A ".." that follows a
directory which really exists keeps working by the real directory relations.
The registry path may be a
symbolic link to an existing registry file: new batches are saved into the
linked file (a relative link target is resolved against the link's own
directory), the link itself is left untouched and the target keeps its
permissions. A symbolic link may also sit on a DIRECTORY component of the
path, together with "..": reads and saves resolve the path the way the
filesystem does, so with work/alias -> store/child the path
work/alias/../batches.json names store/batches.json, and a new batch is
appended to that real file rather than to a same-named file in the link's
parent directory. The temporary file is prepared in the real file's own
directory, so a read-only work directory (read and enter, but not create)
does not block the save and nothing is created under work; only an
unwritable real target directory rejects it. A link whose target does not
exist, or a loop of links, is rejected — the target is never created and
the link is never replaced. An
existing file that is empty, cannot be read in this format, or contains
several records with the same batch number is rejected outright and never
overwritten. "This format"
is strict: the root object must carry exactly version (the integer 1) and
batches (an array, empty allowed), each record exactly the four lowercase
fields batch, product, quantity and unit; missing, null, mistyped, unknown
or case-variant fields (Version, Batch, ...) are rejected, and so is any
field appearing twice in one object — even with identical values, even when
one spelling hides behind a JSON escape. The error names the file, the
field and the reason, plus the 1-based record position (and the batch id
when it is unambiguous) for record-level problems. Failures print
the reason to stderr and exit non-zero without touching the registry.
`
}

func runBatchRegister(args []string, stdout io.Writer) error {
	fs := flag.NewFlagSet("batch-register", flag.ContinueOnError)
	fs.SetOutput(io.Discard)
	registryPath := fs.String("registry", "", "registry `file` to read and write")
	batchRaw := fs.String("batch", "", "batch number (unique within the registry)")
	productRaw := fs.String("product", "", "product number")
	quantityRaw := fs.String("quantity", "", "positive decimal integer quantity")
	unitRaw := fs.String("unit", "", "measurement unit")
	if err := fs.Parse(args); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			fmt.Fprint(stdout, rootUsage())
			return nil
		}
		return &usageError{msg: "batch-register: " + err.Error(), usage: batchRegisterUsage}
	}
	if fs.NArg() != 0 {
		return &usageError{
			msg:   fmt.Sprintf("batch-register: unexpected positional argument(s): %s", strings.Join(fs.Args(), " ")),
			usage: batchRegisterUsage,
		}
	}

	// Missing or malformed input must never create or modify the registry
	// file, so required flags are checked before reading or writing anything.
	required := []struct {
		name  string
		value string
	}{
		{"--registry", *registryPath},
		{"--batch", *batchRaw},
		{"--product", *productRaw},
		{"--quantity", *quantityRaw},
		{"--unit", *unitRaw},
	}
	var missing []string
	for _, f := range required {
		if f.value == "" {
			missing = append(missing, f.name)
		}
	}
	if len(missing) > 0 {
		return &usageError{
			msg:   "batch-register: missing required flag(s): " + strings.Join(missing, ", "),
			usage: batchRegisterUsage,
		}
	}

	batch, err := batchreg.NormalizeField(*batchRaw)
	if err != nil {
		return &usageError{msg: "batch-register: invalid --batch: " + err.Error(), usage: batchRegisterUsage}
	}
	product, err := batchreg.NormalizeField(*productRaw)
	if err != nil {
		return &usageError{msg: "batch-register: invalid --product: " + err.Error(), usage: batchRegisterUsage}
	}
	unit, err := batchreg.NormalizeField(*unitRaw)
	if err != nil {
		return &usageError{msg: "batch-register: invalid --unit: " + err.Error(), usage: batchRegisterUsage}
	}
	quantity, err := batchreg.ParseQuantity(*quantityRaw)
	if err != nil {
		return &usageError{msg: "batch-register: invalid --quantity: " + err.Error(), usage: batchRegisterUsage}
	}

	reg, existed, err := batchreg.Load(*registryPath)
	if err != nil {
		return err
	}
	outcome, err := batchreg.Register(reg, batchreg.Input{
		Batch: batch, Product: product, Quantity: quantity, Unit: unit,
	})
	if err != nil {
		return err
	}
	if outcome.Created {
		if err := batchreg.Save(*registryPath, reg); err != nil {
			if !existed {
				// Nothing was registered before; drop any partial new file.
				removePartialNewRegistry(*registryPath)
			}
			return err
		}
	}

	status := "duplicate"
	if outcome.Created {
		status = "created"
	}
	result := struct {
		Batch    string `json:"batch"`
		Product  string `json:"product"`
		Quantity int64  `json:"quantity"`
		Unit     string `json:"unit"`
		Status   string `json:"status"`
	}{
		Batch:    outcome.Batch.Batch,
		Product:  outcome.Batch.Product,
		Quantity: outcome.Batch.Quantity,
		Unit:     outcome.Batch.Unit,
		Status:   status,
	}
	payload, err := json.Marshal(result)
	if err != nil {
		return err
	}
	_, err = fmt.Fprintln(stdout, string(payload))
	return err
}

func runBatchImport(args []string, stdout io.Writer) error {
	fs := flag.NewFlagSet("batch-import", flag.ContinueOnError)
	fs.SetOutput(io.Discard)
	registryPath := fs.String("registry", "", "registry `file` to read and write")
	inputPath := fs.String("input", "", "read-only JSON manifest `file` to import")
	if err := fs.Parse(args); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			fmt.Fprint(stdout, rootUsage())
			return nil
		}
		return &usageError{msg: "batch-import: " + err.Error(), usage: batchImportUsage}
	}
	if fs.NArg() != 0 {
		return &usageError{
			msg:   fmt.Sprintf("batch-import: unexpected positional argument(s): %s", strings.Join(fs.Args(), " ")),
			usage: batchImportUsage,
		}
	}
	if *registryPath == "" || *inputPath == "" {
		var missing []string
		if *registryPath == "" {
			missing = append(missing, "--registry")
		}
		if *inputPath == "" {
			missing = append(missing, "--input")
		}
		return &usageError{
			msg:   "batch-import: missing required flag(s): " + strings.Join(missing, ", "),
			usage: batchImportUsage,
		}
	}

	// The manifest is read-only and is parsed (and fully validated) before
	// the registry is loaded or written, so bad input cannot touch it.
	data, err := os.ReadFile(*inputPath)
	if err != nil {
		return fmt.Errorf("batch-import: cannot read input file %q: %w", *inputPath, err)
	}
	inputs, err := batchreg.ParseManifest(data)
	if err != nil {
		return fmt.Errorf("batch-import: invalid input file %q: %w", *inputPath, err)
	}

	reg, existed, err := batchreg.Load(*registryPath)
	if err != nil {
		return fmt.Errorf("batch-import: %w", err)
	}
	outcomes, err := batchreg.Import(reg, inputs)
	if err != nil {
		return fmt.Errorf("batch-import: %w", err)
	}

	type importResultJSON struct {
		Batch    string `json:"batch"`
		Product  string `json:"product"`
		Quantity int64  `json:"quantity"`
		Unit     string `json:"unit"`
		Status   string `json:"status"`
	}
	results := make([]importResultJSON, len(outcomes))
	anyCreated := false
	for i, o := range outcomes {
		status := "duplicate"
		if o.Created {
			status = "created"
			anyCreated = true
		}
		results[i] = importResultJSON{
			Batch:    o.Batch.Batch,
			Product:  o.Batch.Product,
			Quantity: o.Batch.Quantity,
			Unit:     o.Batch.Unit,
			Status:   status,
		}
	}

	// An all-duplicate manifest must leave bytes and mtime untouched, so the
	// registry is written only when at least one record was newly created.
	if anyCreated {
		if err := batchreg.Save(*registryPath, reg); err != nil {
			if !existed {
				// The registry never existed before this import; drop any
				// partial new file so a failed save leaves nothing behind.
				removePartialNewRegistry(*registryPath)
			}
			return fmt.Errorf("batch-import: %w", err)
		}
	}

	payload, err := json.Marshal(struct {
		Results []importResultJSON `json:"results"`
	}{Results: results})
	if err != nil {
		return fmt.Errorf("batch-import: %w", err)
	}
	_, err = fmt.Fprintln(stdout, string(payload))
	if err != nil {
		return fmt.Errorf("batch-import: %w", err)
	}
	return nil
}

// removePartialNewRegistry drops a partially written new registry file after
// a failed first save. A symbolic link is never removed: the link is the
// user's pointer to the real registry file, not a partial creation of this
// run.
func removePartialNewRegistry(path string) {
	info, err := os.Lstat(path)
	if err != nil || info.Mode()&os.ModeSymlink != 0 {
		return
	}
	os.Remove(path)
}

func runDemo() {
	proposal := govflow.Proposal{ID: "gip-7", Title: "fund the audit workstream", State: "voting", Quorum: 1000,
		TimelockEnd: 5000, Actions: []string{"transfer:audits:25000"}}
	if err := govflow.Vote(&proposal, 700, true); err != nil {
		fmt.Println("vote refused:", err)
	}
	if err := govflow.Vote(&proposal, 200, false); err != nil {
		fmt.Println("vote refused:", err)
	}
	next := govflow.Tally(&proposal)
	fmt.Printf("proposal=%s for=%d against=%d quorum=%d next=%s\n", proposal.ID, proposal.ForVotes, proposal.AgainstVotes, proposal.Quorum, next)
	proposal.State = next
	proposal.TimelockEnd = 400
	fmt.Println("executable now:", govflow.Executable([]govflow.Proposal{proposal}, 1000))
}

