12	// This file is the regression net for a registry path that the user spells as
13	// a DIRECTORY location rather than a file. The rule under guard:
14	//
15	//   - a path ending in one or more separators ("store/new.json/"), or whose
16	//     final component is "." or ".." ("store/new/.", "store/new/.."), denotes
17	//     a directory and can never name the registry file;
18	//   - Load and Save refuse it on the spelling alone, with a
19	//     *DirectoryPathError carrying the exact caller-supplied path, whether
20	//     the location does not exist yet, already is a directory, or has a
21	//     regular file directly beneath the spelled directory name;
22	//   - the refusal creates nothing: no missing parent directory, no registry
23	//     file or temporary file at the name left after stripping the trailing
24	//     separator or the final "."/"..", and an existing regular file keeps its
25	//     bytes, permissions and modification time while an existing directory or
26	//     symbolic link is never replaced;
27	//   - the caller's submitted records keep their content and order;
28	//   - relative and absolute spellings of the same directory structure behave
29	//     identically.
30	//
31	// Ordinary file paths are preserved, including one without a ".json" suffix,
32	// a doubled separator in the middle, a first registration whose parent does
33	// not exist, and a "." or ".." in a MIDDLE component.
34	
35	// assertDirectoryPathError checks the shared error contract: a
36	// *DirectoryPathError whose Path is the exact user spelling, and a message
37	// quoting that path, stating that the target must be a file and that this
38	// path denotes a directory.
39	func assertDirectoryPathError(t *testing.T, err error, userPath string) {
40		t.Helper()
41		if err == nil {
42			t.Fatalf("the directory-denoting path %q must be rejected", userPath)
43		}
44		var de *DirectoryPathError
45		if !errors.As(err, &de) {
46			t.Fatalf("want *DirectoryPathError for %q, got %T: %v", userPath, err, err)
47		}
48		if de.Path != userPath {
49			t.Errorf("DirectoryPathError.Path = %q, want the exact supplied path %q", de.Path, userPath)
50		}
51		msg := err.Error()
52		for _, want := range []string{
53			strconv.Quote(userPath),
54			"must be a file",
55			"directory",
56		} {
57			if !strings.Contains(msg, want) {
58				t.Errorf("error %q must contain %q", msg, want)
59			}
60		}
61	}
62	
63	// assertNothingCreated fails if any file (other than the explicitly allowed
64	// names, matched by base name) exists under root — this catches both the
65	// stripped-name registry file and a leftover temporary file.
66	func assertNothingCreated(t *testing.T, root string, allowed ...string) {
67		t.Helper()
68		keep := map[string]bool{}
69		for _, n := range allowed {
70			keep[n] = true
71		}
72		err := filepath.WalkDir(root, func(path string, d os.DirEntry, err error) error {
73			if err != nil || d.IsDir() {
74				return nil
75			}
76			// A symbolic link is not a created regular file; the link cases assert
77			// its target text themselves.
78			if d.Type()&os.ModeSymlink != 0 {
79				return nil
80			}
81			if strings.HasPrefix(d.Name(), ".govflow-registry-") {
82				t.Errorf("the rejected save left a temporary file: %s", path)
83			}
84			if !keep[d.Name()] {
85				t.Errorf("the rejected operation created a file: %s", path)
86			}
87			return nil
88		})
89		if err != nil {
90			t.Fatal(err)
91		}
92	}
93	
94	// The directory-marker shapes, assembled WITHOUT filepath.Clean/Join so the
95	// trailing separator and the final "."/".." reach the package exactly as a
96	// user types them. stripped is the plain file a stripping save would wrongly
97	// create ("store/new.json/" would create "store/new.json"; "store/new/."
98	// would create "store/new"), and missingDir is the directory that would have
99	// to be brought into existence first ("new"); it stays "" when the marker
100	// hangs directly off the store directory.
101	func directoryShapeCases(store string) []struct {
102		name       string
103		path       string
104		stripped   string
105		missingDir string
106	} {
107		sep := string(os.PathSeparator)
108		return []struct {
109			name       string
110			path       string
111			stripped   string
112			missingDir string
113		}{
114			{"trailing slash", store + sep + "new.json" + sep, filepath.Join(store, "new.json"), ""},
115			{"two trailing slashes", store + sep + "new.json" + sep + sep, filepath.Join(store, "new.json"), ""},
116			{"final dot", store + sep + "new" + sep + ".", filepath.Join(store, "new"), "new"},
117			{"final dot-dot", store + sep + "new" + sep + "..", filepath.Join(store, "new"), "new"},
118		}
119	}
120	
121	// Save into a location that does not exist must reject every directory-marker
122	// shape and create nothing — not the missing parent, and no plain file at the
123	// name left after stripping the marker.
124	func TestSaveRejectsDirectorySpellingWhenNothingExists(t *testing.T) {
125		for _, tc := range []struct {
126			name string
127			abs  bool
128		}{
129			{"absolute", true},
130			{"relative", false},
131		} {
132			t.Run(tc.name, func(t *testing.T) {
133				root := t.TempDir()
134				store := filepath.Join(root, "store")
135				if err := os.MkdirAll(store, 0o755); err != nil {
136					t.Fatal(err)
137				}
138				if tc.abs {
139					t.Chdir(t.TempDir()) // unrelated cwd: absolute paths stand alone
140				} else {
141					t.Chdir(root)
142				}
143				storeArg := store
144				if !tc.abs {
145					storeArg = "store"
146				}
147				for _, shape := range directoryShapeCases(storeArg) {
148					t.Run(shape.name, func(t *testing.T) {
149						submitted := []Batch{saveBatch("NEW", "P-9", 5, "box")}
150						reg := &Registry{Version: FormatVersion, Batches: append([]Batch(nil), submitted...)}
151						err := Save(shape.path, reg)
152	
153						assertDirectoryPathError(t, err, shape.path)
154						// The stripped location is not written and any directory
155						// that would first have to exist is not brought into being.
156						if _, statErr := os.Lstat(shape.stripped); !os.IsNotExist(statErr) {
157							t.Fatalf("no file may be created at the stripped name %q, stat err=%v", shape.stripped, statErr)
158						}
159						if shape.missingDir != "" {
160							if _, statErr := os.Lstat(shape.missingDir); !os.IsNotExist(statErr) {
161								t.Fatalf("the rejected save must not create missing parent %q, stat err=%v", shape.missingDir, statErr)
162							}
163						}
164						assertNothingCreated(t, root)
165						assertBatchesEqual(t, reg.Batches, submitted)
166					})
167				}
168			})
169		}
170	}
171	
172	// Load of the same shapes is a refusal too — never an empty "fresh" registry
173	// that the command could go on to merge into.
174	func TestLoadRejectsDirectorySpellingWhenNothingExists(t *testing.T) {
175		root := t.TempDir()
176		store := filepath.Join(root, "store")
177		if err := os.MkdirAll(store, 0o755); err != nil {
178			t.Fatal(err)
179		}
180		for _, shape := range directoryShapeCases(store) {
181			t.Run(shape.name, func(t *testing.T) {
182				reg, existed, err := Load(shape.path)
183				assertDirectoryPathError(t, err, shape.path)
184				if reg != nil {
185					t.Errorf("Load must return a nil registry on refusal, got %+v", reg)
186				}
187				if !existed {
188					t.Error("a directory-denoting path must not be reported as a registry that merely does not exist")
189				}
190				assertNothingCreated(t, root)
191			})
192		}
193	}
194	
195	// When the location already IS a directory (or names one through "."), both
196	// Load and Save reject it with the file-vs-directory rule and leave the
197	// directory and its contents exactly as they were.
198	func TestDirectorySpellingOverExistingDirectoryRejected(t *testing.T) {
199		root := t.TempDir()
200		store := filepath.Join(root, "store")
201		dir := filepath.Join(store, "dir")
202		if err := os.MkdirAll(dir, 0o755); err != nil {
203			t.Fatal(err)
204		}
205		// A file inside the directory proves the directory itself survives.
206		inside := filepath.Join(dir, "keep.txt")
207		if err := os.WriteFile(inside, []byte("x"), 0o640); err != nil {
208			t.Fatal(err)
209		}
210		sep := string(os.PathSeparator)
211		paths := []string{
212			dir + sep,
213			dir + sep + sep,
214			dir + sep + ".",
215			dir + sep + "..",
216		}
217		for i, userPath := range paths {
218			t.Run("shape-"+strconv.Itoa(i), func(t *testing.T) {
219				submitted := []Batch{saveBatch("NEW", "P-9", 5, "box")}
220				reg := &Registry{Version: FormatVersion, Batches: append([]Batch(nil), submitted...)}
221	
222				_, existed, lerr := Load(userPath)
223				assertDirectoryPathError(t, lerr, userPath)
224				if !existed {
225					t.Error("a path over an existing directory must not count as a missing registry")
226				}
227				serr := Save(userPath, reg)
228				assertDirectoryPathError(t, serr, userPath)
229	
230				info, err := os.Stat(dir)
231				if err != nil || !info.IsDir() {
232					t.Fatalf("the existing directory must survive as a directory: %+v err=%v", info, err)
233				}
234				if data, err := os.ReadFile(inside); err != nil || string(data) != "x" {
235					t.Fatalf("directory contents changed: data=%q err=%v", data, err)
236				}
237				assertNothingCreated(t, root, "keep.txt")
238				assertBatchesEqual(t, reg.Batches, submitted)
239			})
240		}
241	}
