243	// A regular file sitting directly beneath the spelled directory name is the
244	// exact shape that used to be created or collided with: "store/new.json/"
245	// beside plain file "store/new.json", or "store/new/." beside plain file
246	// "store/new". The operation is rejected and the file keeps its bytes,
247	// permissions and pinned modification time.
248	func TestDirectorySpellingOverRegularFileBeneathIsRejected(t *testing.T) {
249		const oldContent = `{"version":1,"batches":[{"batch":"OLD","product":"P-1","quantity":10,"unit":"kg"}]}`
250		sep := string(os.PathSeparator)
251		cases := []struct {
252			name string
253			file string
254			path string
255		}{
256			{
257				"trailing slash beside new.json",
258				"new.json", "new.json" + sep,
259			},
260			{
261				"two trailing slashes beside new.json",
262				"new.json", "new.json" + sep + sep,
263			},
264			{
265				"dot component beside new.json",
266				"new.json", "new.json" + sep + ".",
267			},
268			{
269				"dot-dot component beside new.json",
270				"new.json", "new.json" + sep + "..",
271			},
272			{
273				"dot component beside plain new",
274				"new", "new" + sep + ".",
275			},
276			{
277				"dot-dot component beside plain new",
278				"new", "new" + sep + "..",
279			},
280		}
281		for _, tc := range cases {
282			t.Run(tc.name, func(t *testing.T) {
283				root := t.TempDir()
284				store := filepath.Join(root, "store")
285				if err := os.MkdirAll(store, 0o755); err != nil {
286					t.Fatal(err)
287				}
288				existing := filepath.Join(store, tc.file)
289				writeRegistry(t, existing, oldContent)
290				if err := os.Chmod(existing, 0o600); err != nil {
291					t.Fatal(err)
292				}
293				pinned := pinFile(t, existing)
294				// Raw join: filepath.Join/Clean would erase the trailing marker.
295				userPath := store + sep + tc.path
296	
297				submitted := []Batch{saveBatch("NEW", "P-9", 5, "box")}
298				reg := &Registry{Version: FormatVersion, Batches: append([]Batch(nil), submitted...)}
299	
300				_, existed, lerr := Load(userPath)
301				assertDirectoryPathError(t, lerr, userPath)
302				if !existed {
303					t.Error("the occupied location must not be treated as a missing registry")
304				}
305				serr := Save(userPath, reg)
306				assertDirectoryPathError(t, serr, userPath)
307	
308				info, err := os.Stat(existing)
309				if err != nil {
310					t.Fatal(err)
311				}
312				if !info.Mode().IsRegular() {
313					t.Fatalf("the existing file must stay a regular file, mode %v", info.Mode())
314				}
315				if info.Mode().Perm() != 0o600 {
316					t.Errorf("the existing file permissions changed: got %o want 0600", info.Mode().Perm())
317				}
318				if !info.ModTime().Equal(pinned) {
319					t.Errorf("the existing file mtime changed: got %v want %v", info.ModTime(), pinned)
320				}
321				data, err := os.ReadFile(existing)
322				if err != nil {
323					t.Fatal(err)
324				}
325				if string(data) != oldContent {
326					t.Fatalf("the existing file bytes changed:\n%s", data)
327				}
328				assertNothingCreated(t, root, filepath.Base(existing))
329				assertBatchesEqual(t, mustLoad(t, existing).Batches,
330					[]Batch{saveBatch("OLD", "P-1", 10, "kg")})
331				assertBatchesEqual(t, reg.Batches, submitted)
332			})
333		}
334	}
335	
336	// A symbolic link is never replaced or chased into a write: a link to a file
337	// addressed with a directory marker, and a link to a directory addressed the
338	// same way, are both rejected while the link and its target stay intact.
339	func TestDirectorySpellingThroughSymlinkRejected(t *testing.T) {
340		t.Run("symlink to registry file", func(t *testing.T) {
341			root := t.TempDir()
342			store := filepath.Join(root, "store")
343			if err := os.MkdirAll(store, 0o755); err != nil {
344				t.Fatal(err)
345			}
346			const oldContent = `{"version":1,"batches":[{"batch":"OLD","product":"P-1","quantity":10,"unit":"kg"}]}`
347			target := filepath.Join(root, "real-registry.json")
348			writeRegistry(t, target, oldContent)
349			pinned := pinFile(t, target)
350			link := filepath.Join(store, "link")
351			if err := os.Symlink(target, link); err != nil {
352				t.Fatal(err)
353			}
354			for _, userPath := range []string{
355				link + string(os.PathSeparator),
356				link + string(os.PathSeparator) + ".",
357			} {
358				submitted := []Batch{saveBatch("NEW", "P-9", 5, "box")}
359				reg := &Registry{Version: FormatVersion, Batches: append([]Batch(nil), submitted...)}
360				assertDirectoryPathError(t, Save(userPath, reg), userPath)
361				got, err := os.Readlink(link)
362				if err != nil || got != target {
363					t.Fatalf("the link must be untouched: target=%q err=%v", got, err)
364				}
365				if info, err := os.Stat(target); err != nil || !info.ModTime().Equal(pinned) {
366					t.Fatalf("the link target must be untouched: info=%+v err=%v", info, err)
367				}
368				if data, _ := os.ReadFile(target); string(data) != oldContent {
369					t.Fatalf("the link target bytes changed:\n%s", data)
370				}
371				assertBatchesEqual(t, reg.Batches, submitted)
372			}
373			assertNothingCreated(t, root, filepath.Base(target))
374		})
375	
376		t.Run("symlink to directory", func(t *testing.T) {
377			root := t.TempDir()
378			store := filepath.Join(root, "store")
379			realDir := filepath.Join(root, "realdir")
380			if err := os.MkdirAll(realDir, 0o755); err != nil {
381				t.Fatal(err)
382			}
383			registry := filepath.Join(realDir, "batches.json")
384			const oldContent = `{"version":1,"batches":[{"batch":"OLD","product":"P-1","quantity":10,"unit":"kg"}]}`
385			writeRegistry(t, registry, oldContent)
386			pinned := pinFile(t, registry)
387			if err := os.MkdirAll(store, 0o755); err != nil {
388				t.Fatal(err)
389			}
390			link := filepath.Join(store, "dlink")
391			if err := os.Symlink(realDir, link); err != nil {
392				t.Fatal(err)
393			}
394			userPath := link + string(os.PathSeparator)
395			reg := &Registry{Version: FormatVersion, Batches: []Batch{saveBatch("NEW", "P-9", 5, "box")}}
396			assertDirectoryPathError(t, Save(userPath, reg), userPath)
397			if got, err := os.Readlink(link); err != nil || got != realDir {
398				t.Fatalf("the directory link must be untouched: target=%q err=%v", got, err)
399			}
400			if info, err := os.Stat(registry); err != nil || !info.ModTime().Equal(pinned) {
401				t.Fatalf("a registry inside the linked directory must be untouched: info=%+v err=%v", info, err)
402			}
403			assertNothingCreated(t, root, "batches.json")
404		})
405	}
406	
407	// Bare "." and ".." (the whole path is one directory component) and a trailing
408	// slash on the working directory are refused too.
409	func TestSaveRejectsBareDirectoryComponents(t *testing.T) {
410		root := t.TempDir()
411		t.Chdir(root)
412		for _, userPath := range []string{".", "..", "." + string(os.PathSeparator)} {
413			submitted := []Batch{saveBatch("NEW", "P-9", 5, "box")}
414			reg := &Registry{Version: FormatVersion, Batches: append([]Batch(nil), submitted...)}
415			assertDirectoryPathError(t, Save(userPath, reg), userPath)
416			assertDirectoryPathError(t, func() error {
417				_, _, err := Load(userPath)
418				return err
419			}(), userPath)
420			assertNothingCreated(t, root)
421			assertBatchesEqual(t, reg.Batches, submitted)
422		}
423	}
424	
425	// Normal file paths keep working exactly as before: no ".json" suffix
426	// required, a doubled separator in the middle is harmless, a first
427	// registration into a not-yet-existing parent creates the directory and the
428	// file, and a "." or ".." in a MIDDLE component resolves ordinarily.
429	func TestSaveNormalFilePathsStillWork(t *testing.T) {
430		want := []Batch{saveBatch("NEW", "P-9", 5, "box")}
431	
432		t.Run("no extension and missing parent", func(t *testing.T) {
433			path := filepath.Join(t.TempDir(), "store", "new", "batches")
434			reg := &Registry{Version: FormatVersion, Batches: append([]Batch(nil), want...)}
435			if err := Save(path, reg); err != nil {
436				t.Fatalf("a normal file path without a .json suffix must save: %v", err)
437			}
438			assertBatchesEqual(t, mustLoad(t, path).Batches, want)
439		})
440	
441		t.Run("doubled middle separator", func(t *testing.T) {
442			dir := t.TempDir()
443			path := filepath.Join(dir, "store") + string(os.PathSeparator) + string(os.PathSeparator) + "b.json"
444			reg := &Registry{Version: FormatVersion, Batches: append([]Batch(nil), want...)}
445			if err := Save(path, reg); err != nil {
446				t.Fatalf("a doubled separator in the middle must not reject the save: %v", err)
447			}
448			assertBatchesEqual(t, mustLoad(t, filepath.Join(dir, "store", "b.json")).Batches, want)
449		})
450	
451		t.Run("middle dot and dot-dot", func(t *testing.T) {
452			root := t.TempDir()
453			registry := filepath.Join(root, "store", "batches.json")
454			writeRegistry(t, registry, `{"version":1,"batches":[{"batch":"OLD","product":"P-1","quantity":10,"unit":"kg"}]}`)
455			if err := os.MkdirAll(filepath.Join(root, "store", "child"), 0o755); err != nil {
456				t.Fatal(err)
457			}
458			for _, userPath := range []string{
459				filepath.Join(root, "store", ".", "batches.json"),
460				filepath.Join(root, "store", "child", "..", "batches.json"),
461			} {
462				reg := mustLoad(t, userPath)
463				if _, err := Register(reg, Input{Batch: "NEW", Product: "P-9", Quantity: 5, Unit: "box"}); err != nil {
464					t.Fatal(err)
465				}
466				if err := Save(userPath, reg); err != nil {
467					t.Fatalf("a middle %q must resolve by the ordinary rules: %v", userPath, err)
468				}
469			}
470			assertBatchesEqual(t, mustLoad(t, registry).Batches, []Batch{
471				saveBatch("OLD", "P-1", 10, "kg"),
472				saveBatch("NEW", "P-9", 5, "box"),
473			})
474		})
475	}
476

