1	package main
2	
3	import (
4		"bytes"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9	)
10	
11	// End-to-end regression for a --registry that reaches the file through a
12	// DIRECTORY symbolic link whose target directory does not exist. With
13	// work/alias -> ../store/missing-child and that target absent, neither
14	// work/alias/batches.json nor work/alias/../batches.json names a file the
15	// kernel can open; the latter must not collapse onto the valid
16	// work/batches.json beside the link. Load must reject the path before
17	// registration proceeds, so both commands fail: the error names the exact
18	// user-supplied registry path and the unresolvable symbolic link (it does
19	// not announce a merely not-yet-created registry), stdout carries no success
20	// result, the link is untouched, the missing target is not created, and an
21	// existing same-named file keeps its bytes and modification time.
22	
23	// danglingDirLinkCLIFixture builds root/work/alias -> linkTarget with the
24	// target missing and returns the link directory and path.
25	func danglingDirLinkCLIFixture(t *testing.T, root, linkTarget string) (workDir, aliasPath string) {
26		t.Helper()
27		workDir = filepath.Join(root, "work")
28		if err := os.MkdirAll(workDir, 0o755); err != nil {
29			t.Fatal(err)
30		}
31		aliasPath = filepath.Join(workDir, "alias")
32		if err := os.Symlink(linkTarget, aliasPath); err != nil {
33			t.Fatal(err)
34		}
35		return workDir, aliasPath
36	}
37	
38	// assertDanglingDirLinkCommandFailure checks the process-visible contract
39	// shared by both commands: a non-nil error quoting the exact registry path
40	// and naming the symbolic link, no success payload on stdout, the link
41	// intact and nothing created at the missing target.
42	func assertDanglingDirLinkCommandFailure(t *testing.T, err error, stdout *bytes.Buffer, userPath, aliasPath, linkTarget, root string, allowedFiles ...string) {
43		t.Helper()
44		if err == nil {
45			t.Fatal("a --registry through a dangling directory link must reject the command")
46		}
47		msg := err.Error()
48		if !strings.Contains(msg, userPath) {
49			t.Errorf("error %q must name the user-supplied registry path %q", msg, userPath)
50		}
51		if !strings.Contains(msg, "symbolic link") {
52			t.Errorf("error %q must state the path runs into an unusable symbolic link", msg)
53		}
54		if strings.Contains(msg, "has not been created") {
55			t.Errorf("error %q must not pretend the registry file has merely not been created", msg)
56		}
57		if stdout.Len() != 0 {
58			t.Errorf("stdout must carry no success result, got %q", stdout.String())
59		}
60		assertStillSymlink(t, aliasPath, linkTarget)
61		if _, statErr := os.Lstat(filepath.Join(root, "store")); !os.IsNotExist(statErr) {
62			t.Errorf("the missing link target must not be created, stat err=%v", statErr)
63		}
64		// The directory link itself is not a leftover save artifact.
65		allowed := append([]string{"alias"}, allowedFiles...)
66		assertNoSaveLeftovers(t, root, allowed...)
67	}
68	
69	// Both commands reject a registry reached straight through a dangling
70	// directory link, for relative and absolute link targets alike.
71	func TestBatchCommandsRejectDanglingDirectorySymlink(t *testing.T) {
72		manifestContent := `[{"batch":"B1","product":"P","quantity":1,"unit":"kg"}]`
73		cases := []struct {
74			name       string
75			linkTarget func(root string) string
76		}{
77			{"relative target", func(root string) string {
78				return filepath.Join("..", "store", "missing-child")
79			}},
80			{"absolute target", func(root string) string {
81				return filepath.Join(root, "store", "missing-child")
82			}},
83		}
84		for _, tc := range cases {
85			t.Run(tc.name, func(t *testing.T) {
86				for _, command := range []string{"batch-register", "batch-import"} {
87					t.Run(command, func(t *testing.T) {
88						root := t.TempDir()
89						linkTarget := tc.linkTarget(root)
90						workDir, aliasPath := danglingDirLinkCLIFixture(t, root, linkTarget)
91						manifestPath := filepath.Join(root, "in.json")
92						writeFile(t, manifestPath, manifestContent)
93						userPath := filepath.Join(aliasPath, "batches.json")
94	
